function jlEscape(zx, zy, cx, cy, maxIter){
  var x=zx, y=zy, i=0;
  while(i<maxIter && x*x+y*y<=4){
    var nx=x*x-y*y+cx, ny=2*x*y+cy;
    x=nx; y=ny; i++;
  }
  if(i>=maxIter) return { iter:maxIter, inside:true, smooth:maxIter };
  var mag=Math.sqrt(x*x+y*y);
  var sm=i+1-Math.log(Math.log(Math.max(mag,1.0000001)))/Math.LN2;
  return { iter:i, inside:false, smooth:Math.max(0,sm) };
}
function jlMap(px, py, w, h, scale){
  scale=scale||1.6;
  return { x:(px-w/2)/(w/2)*scale, y:(py-h/2)/(h/2)*scale*h/w };
}
function jlColor(smooth, maxIter){
  if(smooth>=maxIter) return [10,10,11];
  var t=Math.min(1,smooth/maxIter);
  var h=(220+t*160)%360, s=0.7, l=0.16+0.5*Math.pow(t,0.5);
  var c=(1-Math.abs(2*l-1))*s, hp=h/60, xx=c*(1-Math.abs(hp%2-1));
  var r=0,g=0,b=0;
  if(hp<1){r=c;g=xx;} else if(hp<2){r=xx;g=c;} else if(hp<3){g=c;b=xx;} else if(hp<4){g=xx;b=c;} else if(hp<5){r=xx;b=c;} else {r=c;b=xx;}
  var m=l-c/2;
  return [Math.round((r+m)*255),Math.round((g+m)*255),Math.round((b+m)*255)];
}
function jlPresets(){ return { seahorse:[-0.7,0.27015], swirl:[-0.4,0.6], nebula:[0.285,0.01], lightning:[-0.8,0.156], dragon:[-0.70176,-0.3842] }; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { jlEscape:jlEscape, jlMap:jlMap, jlColor:jlColor, jlPresets:jlPresets };
}
if (typeof window !== 'undefined') {
  window.JuliaForgePure = { jlEscape:jlEscape, jlMap:jlMap, jlColor:jlColor, jlPresets:jlPresets };
}
